INSERT INTO miaradi_circuit_pages
  (circuit_id, hero_title_fr, hero_title_en, intro_fr, intro_en, hero_image, itinerary_json, is_published)
SELECT c.id,
       'De Boeny Aranta aux Tsingy sauvages de Namoroka',
       'From Boeny Aranta to the wild Tsingy of Namoroka',
       'Un voyage au cœur des trésors méconnus du Boeny, entre héritage des anciens navigateurs, traditions des villages côtiers et paysages spectaculaires des Tsingy de Namoroka. Loin des itinéraires touristiques habituels, ce circuit vous invite à découvrir un Nord-Ouest malgache authentique, où la mer et la terre racontent chacune une histoire. Nous commençons par une navigation à travers la baie de Bombetoka pour rejoindre l’îlot d’Antsoheribory et Boeny Aranta. Les vestiges d’anciennes installations arabes témoignent d’un passé marqué par les échanges maritimes. Nous partons ensuite à la rencontre des communautés côtières issues des Antalaotsy, avant de traverser les paysages de brousse jusqu’à Soalala et au parc national de Namoroka. Le voyage se termine par une traversée de la région jusqu’à Katsepy, puis une excursion dans la baie de Bombetoka à la recherche des flamants roses, avant de retrouver Majunga.',
       'A journey into the lesser-known treasures of Boeny, between maritime heritage, coastal village traditions and the spectacular Tsingy of Namoroka.',
       'assets/images/circuits/majunga.jpg',
       '[{"title":"Arrivée à Majunga : bienvenue dans le Boeny","subtitle":"Accueil et première découverte de la ville","description":"À votre arrivée à l’aéroport de Majunga, l’équipe MIARADI vous accueille et vous accompagne jusqu’à votre hôtel. Après le transfert et votre installation, vous profitez librement de cette première journée pour vous reposer et vous imprégner de l’atmosphère de la ville. Majunga, avec son ambiance côtière, son métissage culturel et sa douceur de vivre, constitue le point de départ idéal de notre aventure dans le Boeny.","overnight":"Nuitée à l’hôtel à Majunga.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Majunga et le Boeny"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/The_baobab%2C_Mahajanga.jpg?width=1200","alt":"Le baobab de Majunga"}]},{"title":"Majunga – Boeny Aranta : sur les traces des anciens navigateurs","subtitle":"Navigation dans la baie de Bombetoka","description":"Ce matin, nous quittons le port de Majunga à bord d’une vedette rapide. Nous naviguons à travers la baie de Bombetoka, en direction de Boeny Aranta et de l’îlot d’Antsoheribory. Au fil de l’eau, les paysages de la baie se dévoilent : mangroves, rives sauvages et petits villages côtiers. Nous découvrons les vestiges d’anciennes installations arabes, témoins du rôle joué par cette région dans les échanges maritimes de l’océan Indien. Après le déjeuner sur l’île, nous rejoignons un village de pêcheurs et rencontrons ses habitants, descendants des Antalaotsy, pour découvrir leur quotidien et leurs traditions.","overnight":"Nuitée en bivouac sur l’îlot.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Baie de Bombetoka"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/The_baobab%2C_Mahajanga.jpg?width=1200","alt":"Paysage côtier du Boeny"}]},{"title":"Boeny Aranta – Soalala : de la mer aux terres de brousse","subtitle":"Villages côtiers et route vers l’intérieur","description":"Après le petit-déjeuner, nous quittons l’îlot en pirogue traditionnelle pour rejoindre la terre ferme. Nous poursuivons notre aventure en 4x4 vers Soalala, en nous enfonçant progressivement dans les terres du Boeny. Les rives maritimes laissent place aux étendues de brousse, aux villages ruraux et aux pistes de l’intérieur. En chemin, nous traversons la région de Namakia, connue pour ses cultures de canne à sucre et son activité de production de sucre et de rhum. Pause déjeuner pique-nique sur la route, puis arrivée à Soalala et installation à l’hôtel.","overnight":"Nuitée à l’hôtel à Soalala.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Paysages du Boeny"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/The_baobab%2C_Mahajanga.jpg?width=1200","alt":"Paysage de l’Ouest malgache"}]},{"title":"Soalala – Namoroka : aux portes des Tsingy","subtitle":"Pistes, villages et installation au campement","description":"Nous reprenons la piste en 4x4 en direction du parc national de Namoroka. Cette étape nous conduit dans une région reculée où se succèdent rizières, forêts de raphia, végétation de brousse et petits villages éloignés des grands axes. Nous découvrons un Madagascar rural où la vie quotidienne reste étroitement liée à la terre et aux ressources naturelles. Nous atteignons Vilanandro, petit village situé aux portes des Tsingy de Namoroka. Installation de notre campement, puis balade dans le village pour découvrir son environnement et faire connaissance avec ses habitants.","overnight":"Nuitée au campement.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Paysages vers Namoroka"}]},{"title":"Namoroka : exploration des Tsingy sauvages","subtitle":"Une journée au cœur d’un paysage karstique remarquable","description":"Une journée entière est consacrée à la découverte des Tsingy de Namoroka, l’un des paysages karstiques les plus remarquables et les plus confidentiels de Madagascar. Nous explorons cet univers minéral façonné au fil des millénaires par l’érosion : aiguilles calcaires, reliefs déchiquetés, passages naturels et formations rocheuses spectaculaires. Avec notre guide, nous prenons le temps d’observer la richesse naturelle du site, ses paysages et, avec un peu de chance, quelques représentants de sa faune.","overnight":"Nuitée au campement.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy_de_Bemaraha.jpg?width=1400","alt":"Formations calcaires des Tsingy"},{"url":"assets/images/circuits/majunga.jpg","alt":"Paysages de l’Ouest malgache"}]},{"title":"Namoroka – Soalala : retour vers la baie de Baly","subtitle":"Retour par les pistes du Boeny","description":"Après le petit-déjeuner, nous quittons Vilanandro et reprenons la piste en 4x4 en direction de Soalala. Nous retrouvons progressivement les paysages traversés à l’aller, avec leurs villages isolés, leurs rizières et leurs étendues de brousse. À l’arrivée à Soalala, installation à l’hôtel et après-midi libre pour profiter d’un moment de repos après cette immersion dans les Tsingy.","overnight":"Nuitée à l’hôtel à Soalala.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Retour vers Soalala"}]},{"title":"Soalala – Katsepy : une traversée des paysages du Boeny","subtitle":"De l’arrière-pays à la côte","description":"Aujourd’hui, nous prenons la route en direction de Katsepy, à travers les pistes de terre rouge du Boeny. La journée est consacrée à la découverte de l’arrière-pays : villages isolés, palmiers, paysages de brousse et scènes de vie rurale accompagnent notre progression. Nous retrouvons progressivement l’environnement côtier et arrivons à Katsepy en fin d’après-midi. Installation à l’hôtel et soirée libre.","overnight":"Nuitée à Katsepy.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Paysages du Boeny vers Katsepy"}]},{"title":"Katsepy – Baie de Bombetoka – Majunga : les flamants roses et les couleurs de la ville","subtitle":"Excursion dans la baie et découverte de Majunga","description":"Nous commençons la journée par une excursion en mer à bord d’une vedette rapide, à la recherche des flamants roses qui fréquentent les zones humides de la baie de Bombetoka. La navigation permet d’apprécier les paysages de la baie, ses mangroves et ses espaces naturels. Nous rejoignons Majunga vers midi. L’après-midi, découverte de la ville en tuk-tuk : quartiers, maisons d’influence arabe, marchés animés et port aux boutres. Pour terminer la journée, nous retrouvons le bord de mer et le célèbre baobab centenaire de Majunga pour un dernier coucher de soleil sur la côte Ouest.","overnight":"Nuitée à l’hôtel à Majunga.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Majunga et sa baie"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/The_baobab%2C_Mahajanga.jpg?width=1200","alt":"Baobab de Majunga"}]},{"title":"Départ de Majunga : fin de notre aventure dans le Boeny","subtitle":"Derniers souvenirs du voyage","description":"Après le petit-déjeuner, transfert à l’aéroport de Majunga pour votre départ. Nous terminons ce voyage avec de beaux souvenirs : les rencontres avec les communautés côtières, les vestiges d’Antsoheribory, les pistes de brousse, les paysages impressionnants des Tsingy de Namoroka et les couleurs de la baie de Bombetoka.","overnight":"Fin de nos prestations MIARADI.","images":[{"url":"assets/images/circuits/majunga.jpg","alt":"Majunga, dernière étape du voyage"}]}]',
       1
FROM miaradi_circuits c
WHERE c.slug='perles-originelles-majunga'
ON DUPLICATE KEY UPDATE
  hero_title_fr=VALUES(hero_title_fr),
  hero_title_en=VALUES(hero_title_en),
  intro_fr=VALUES(intro_fr),
  intro_en=VALUES(intro_en),
  hero_image=VALUES(hero_image),
  itinerary_json=VALUES(itinerary_json),
  is_published=1;
